// Inverter run state
// 59: run state
// 0x0000 = standby
// 0x0001 = selfcheck
// 0x0002 = normal
// 0x0003 = alarm
// 0x0004 = fault

msg.baseAddr = 59;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 59,
    quantity: 1
};

return msg;

// Temperatures
// 90: Radiator/DC Transformer temp (0.1℃)
// 91: IGBT/AC Radiator temp (0.1℃)
// Note: offset +1000 for display
// -56.2℃ = 438, 0℃ = 1000, 50.5℃ = 1505

msg.baseAddr = 90;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 90,
    quantity: 2
};

return msg;

// Inverter output voltage L1-N
// 154: inverter output voltage L1-N (0.1V)

msg.baseAddr = 154;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 154,
    quantity: 1
};

return msg;

// Inverter output current L1
// 164: Inverter output current L1 (0.01A, signed)

msg.baseAddr = 164;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 164,
    quantity: 1
};

return msg;

// Grid side power
// 167: Grid side L1 power (1W, signed)
// 168: Grid side L2 power (1W, signed)
// 169: Grid total power (1W, signed)
// >0 = buy from grid, <0 = sell to grid

msg.baseAddr = 167;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 167,
    quantity: 3
};

return msg;

// Inverter output total power
// 175: inverter output Total power (1W, signed)

msg.baseAddr = 175;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 175,
    quantity: 1
};

return msg;

// Inverter output frequency
// 193: Inverter output frequency (0.01Hz)

msg.baseAddr = 193;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 193,
    quantity: 1
};

return msg;

// Relay status
// 194: Grid side relay status (0=disconnect, 1=closed)
// 195: Generator side relay status (bit0-3)

msg.baseAddr = 194;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 194,
    quantity: 2
};

return msg;

// Build InverterDeviceState from multiple Modbus reads.
//
// Registers:
// 59      : Run state (0=standby, 1=selfcheck, 2=normal, 3=alarm, 4=fault)
// 90      : Heatsink temp (0.1℃, offset +1000)
// 91      : IGBT temp (0.1℃, offset +1000)
// 154     : Output voltage L1-N (0.1V)
// 164     : Output current L1 (0.01A, signed)
// 167     : Grid side L1 power (1W, signed)
// 168     : Grid side L2 power (1W, signed)
// 169     : Grid total power (1W, signed)
// 175     : Output active power (1W, signed)
// 193     : Output frequency (0.01Hz)
// 194     : Grid relay status (0=disconnect, 1=closed)
// 195     : Generator relay status (bit0-3)
//
// NOTE: outputApparentPowerVA removed - register 84-85 is Load Energy on Hybrid inverters, not apparent power

let raw = msg.payload;

// node-red-contrib-modbus often sends { data: [...], buffer: ... }
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

// Skip string errors
if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

// Determine which block we just read
let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("InverterDeviceState: missing base address on msg");
    return null;
}

// Helper: signed 16-bit
function s16(v) {
    if (!Number.isFinite(v)) return null;
    return (v & 0x8000) ? v - 0x10000 : v;
}

// Helper: map run state code to string
function mapRunState(code) {
    const states = {
        0: "standby",
        1: "selfcheck",
        2: "normal",
        3: "alarm",
        4: "fault"
    };
    return states[code] || "unknown";
}

// ---- Store partials in flow context ----

// Run state 59
if (baseAddr === 59) {
    const stateCode = data[0] || 0;
    flow.set("inv_part_runstate", {
        runState: mapRunState(stateCode)
    });
}

// Temperatures 90-91
else if (baseAddr === 90) {
    // Values have offset +1000 (1000 = 0°C)
    const heatsinkRaw = data[0] || 1000;
    const igbtRaw = data[1] || 1000;

    const heatsinkTemp = (heatsinkRaw - 1000) * 0.1;  // Convert to °C
    const igbtTemp = (igbtRaw - 1000) * 0.1;

    flow.set("inv_part_temps", {
        inverterHeatsinkTempC: Math.round(heatsinkTemp * 10) / 10,
        internalAmbientTempC: Math.round(igbtTemp * 10) / 10
    });
}

// Voltage 154
else if (baseAddr === 154) {
    const voltageRaw = data[0] || 0;  // 0.1V
    const voltage = voltageRaw * 0.1;
    flow.set("inv_part_voltage", {
        outputVoltageV: Math.round(voltage * 10) / 10
    });
}

// Current 164
else if (baseAddr === 164) {
    const currentRaw = s16(data[0]);  // 0.01A, signed
    const current = currentRaw * 0.01;
    flow.set("inv_part_current", {
        outputCurrentA: Math.round(current * 100) / 100
    });
}

// Grid power 167-169
else if (baseAddr === 167) {
    const l1Power = s16(data[0]);   // 1W, signed
    const l2Power = s16(data[1]);   // 1W, signed
    const totalPower = s16(data[2]); // 1W, signed

    flow.set("inv_part_grid_power", {
        gridSidePhaseAPowerW: l1Power,
        gridSidePhaseBPowerW: l2Power,
        gridSidePhaseCPowerW: null,  // Not available for single-phase
        gridSideActivePowerW: totalPower
    });
}

// Output power 175
else if (baseAddr === 175) {
    const power = s16(data[0]);  // 1W, signed
    flow.set("inv_part_output_power", {
        outputActivePowerW: power
    });
}

// Frequency 193
else if (baseAddr === 193) {
    const freqRaw = data[0] || 0;  // 0.01Hz
    const freq = freqRaw * 0.01;
    flow.set("inv_part_freq", {
        outputFrequencyHz: Math.round(freq * 100) / 100
    });
}

// Relay status 194-195
else if (baseAddr === 194) {
    const gridRelay = data[0] || 0;   // 0=disconnect, 1=closed
    const genRelay = data[1] || 0;    // bit0-3 = generator relay status

    flow.set("inv_part_relay", {
        acInputStatus: {
            genGridSignalRaw: (gridRelay << 16) | genRelay,
            gridSignalPresent: gridRelay === 1,
            generatorSignalPresent: (genRelay & 0x0F) > 0
        }
    });
}
else {
    return null;
}

// ---- Try to assemble full state ----

const runstatePart = flow.get("inv_part_runstate");
const tempsPart = flow.get("inv_part_temps");
const voltagePart = flow.get("inv_part_voltage");
const currentPart = flow.get("inv_part_current");
const gridPowerPart = flow.get("inv_part_grid_power");
const outputPowerPart = flow.get("inv_part_output_power");
const freqPart = flow.get("inv_part_freq");
const relayPart = flow.get("inv_part_relay");

// Require all parts
if (!runstatePart || !tempsPart || !voltagePart || 
    !currentPart || !gridPowerPart || !outputPowerPart || !freqPart || !relayPart) {
    return null;
}

// Resolve DeviceId
const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "InverterDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    runState: runstatePart.runState,

    // Output to AC bus
    outputActivePowerW: outputPowerPart.outputActivePowerW,
    outputVoltageV: voltagePart.outputVoltageV,
    outputCurrentA: currentPart.outputCurrentA,
    outputFrequencyHz: freqPart.outputFrequencyHz,

    // Grid-side view
    gridSideActivePowerW: gridPowerPart.gridSideActivePowerW,
    gridSidePhaseAPowerW: gridPowerPart.gridSidePhaseAPowerW,
    gridSidePhaseBPowerW: gridPowerPart.gridSidePhaseBPowerW,
    gridSidePhaseCPowerW: gridPowerPart.gridSidePhaseCPowerW,

    // Temperatures
    inverterHeatsinkTempC: tempsPart.inverterHeatsinkTempC,
    internalAmbientTempC: tempsPart.internalAmbientTempC,

    // AC Input Status
    acInputStatus: relayPart.acInputStatus
};

// Clear partials for next cycle
flow.set("inv_part_runstate", null);
flow.set("inv_part_temps", null);
flow.set("inv_part_voltage", null);
flow.set("inv_part_current", null);
flow.set("inv_part_grid_power", null);
flow.set("inv_part_output_power", null);
flow.set("inv_part_freq", null);
flow.set("inv_part_relay", null);

// Keep snapshot in flow
flow.set("inverterDeviceSnapshot", state);

// Put result on msg
msg.payload = state;
msg.state = state;

return msg;
